def total_gastos(gastos):
    soma = 0
    for valor in gastos:
        soma = soma + valor
    return soma

mesada = float(input("Mesada: "))
gastos = [12.5, 30, 8]
saldo = mesada - total_gastos(gastos)
print("Sobrou:", saldo)
if saldo < 0:
    print("Gastou mais do que recebeu!")
elif saldo >= mesada * 0.2:
    print("Parabéns, guardou 20% ou mais!")
else:
    print("Ainda dá para guardar um pouco.")
